use duration::{parse_duration, ParseError};
fn main() {
    let cases: Vec<(&str, Result<u64, ParseError>)> = vec![
        ("1d2h3m4s", Ok(86400 + 7200 + 180 + 4)),
        ("  1h 30m  ", Ok(5400)),
        ("05m", Ok(300)),
        ("", Err(ParseError::Empty)),
        ("   ", Err(ParseError::Empty)),
        ("1 h", Err(ParseError::Invalid)),
        ("h", Err(ParseError::Invalid)),
        ("1h30", Err(ParseError::Invalid)),
        ("1h1h", Err(ParseError::Invalid)),
        ("30m1h", Err(ParseError::Invalid)),
        ("1H", Err(ParseError::Invalid)),
        ("1s2m", Err(ParseError::Invalid)),
        ("1h30m  ", Ok(5400)),
        ("18446744073709551616s", Err(ParseError::Overflow)),
        ("18446744073709551615s", Ok(18446744073709551615)),
        ("18446744073709551615h", Err(ParseError::Overflow)),
        ("1h", Ok(3600)),
    ];
    let mut bad = 0;
    for (t, want) in cases {
        let got = parse_duration(t);
        if got != want { println!("FAIL {:?}: got {:?} want {:?}", t, got, want); bad += 1; }
    }
    println!("failures: {bad}");
}
EOF
