use duration::{parse_duration, ParseError};

#[test]
fn spec_rules() {
    use ParseError::*;
    // valid
    assert_eq!(parse_duration("1h30m"), Ok(5400));
    assert_eq!(parse_duration("1d"), Ok(86400));
    assert_eq!(parse_duration("1d2h3m4s"), Ok(86400 + 7200 + 180 + 4));
    assert_eq!(parse_duration("05m"), Ok(300));
    assert_eq!(parse_duration("1h 30m"), Ok(5400));
    assert_eq!(parse_duration("  1h 30m  "), Ok(5400));
    assert_eq!(parse_duration("0s"), Ok(0));
    assert_eq!(parse_duration("1h "), Ok(3600));
    assert_eq!(parse_duration("  1h"), Ok(3600));
    // empty
    assert_eq!(parse_duration(""), Err(Empty));
    assert_eq!(parse_duration("   "), Err(Empty));
    // order / repeats
    assert_eq!(parse_duration("30m1h"), Err(Invalid));
    assert_eq!(parse_duration("1h1h"), Err(Invalid));
    assert_eq!(parse_duration("1s1d"), Err(Invalid));
    // space inside part / bad units
    assert_eq!(parse_duration("1 h"), Err(Invalid));
    assert_eq!(parse_duration("1H"), Err(Invalid));
    assert_eq!(parse_duration("1"), Err(Invalid));
    assert_eq!(parse_duration("h"), Err(Invalid));
    assert_eq!(parse_duration("1x"), Err(Invalid));
    assert_eq!(parse_duration("-1h"), Err(Invalid));
    assert_eq!(parse_duration("1h30"), Err(Invalid));
    assert_eq!(parse_duration("1h  30m"), Ok(5400));
    // overflow
    assert_eq!(parse_duration("99999999999999999999s"), Err(Overflow));
    assert_eq!(parse_duration("18446744073709551615s"), Ok(u64::MAX));
    assert_eq!(parse_duration("18446744073709551616s"), Err(Overflow));
    assert_eq!(parse_duration("9999999999999999999d"), Err(Overflow));
    // total overflow but parts fit
    assert_eq!(parse_duration("18446744073709551615s1s"), Err(Invalid)); // order
    assert_eq!(parse_duration("213503982334d1h"), Err(Overflow));
    // leading zeros with huge digit string that is still small
    assert_eq!(parse_duration("0000000000000000000000000000001h"), Ok(3600));
}
EOF
